insert into services (slug, title, short, icon, intro, who_for, approach, you_get, faqs, sort_order) values
  ('weight-management', 'Weight management', 'Sustainable fat loss and healthy weight gain plans built around your routine.', 'weight', 'Whether you want to lose weight, gain it healthily or simply stop yo-yoing, a plan only works if it fits your real life. We build one around your schedule, your family''s food and your budget.', array['You have tried crash diets and the weight keeps coming back', 'You want to gain weight in a healthy, steady way', 'You eat home-cooked food and want a plan that respects that', 'You feel tired, bloated or confused about what to eat']::text[], array['A relaxed first consultation covering your history, routine, sleep, activity and goals', 'A realistic target and timeline, not a quick fix', 'Regular follow-ups so the plan adapts as your body and life change']::text[], array['A personalised meal plan with local, familiar foods', 'Portion and swap guidance for eating out and family meals', 'Follow-up reviews and adjustments', 'Support between sessions for quick questions']::text[], '[{"q":"Will I have to stop eating roti or rice?","a":"No. Plans are built around the food you already eat. We adjust portions and combinations rather than banning foods."},{"q":"How fast will I lose weight?","a":"Healthy progress is steady and varies from person to person. Your dietitian will set a realistic pace with you. Results are not guaranteed."}]'::jsonb, 0),
  ('diabetic-diet-plans', 'Diabetic diet plans', 'Blood-sugar friendly meal plans that still feel like real food.', 'diabetes', 'Living with diabetes or pre-diabetes does not mean a plate of boiled vegetables. A good plan balances carbohydrates, protein and fibre across the day so you feel satisfied and steady.', array['You have type 1, type 2 or gestational diabetes, or pre-diabetes', 'Your sugar readings swing and you want to understand why', 'You want to eat with family without feeling left out', 'You have been told to ''watch your diet'' but not how']::text[], array['Review of your reports, medication timing and daily routine', 'Carbohydrate awareness taught in simple, practical terms', 'A plan designed to work alongside your doctor''s treatment, never replace it']::text[], array['Meal plan matched to your routine and medication schedule', 'Simple guide to portions, swaps and snacks', 'Tips for fasting days, travel and festivals', 'Follow-up to review your readings and adjust']::text[], '[{"q":"Can I still eat sweets?","a":"Occasionally and with planning, many people can. Your plan will show how to fit them in safely."},{"q":"Do I need to stop my medicines?","a":"Never. Diet advice works alongside your doctor''s treatment. Always follow your doctor''s guidance on medication."}]'::jsonb, 1),
  ('uric-acid', 'Uric acid', 'Food guidance to help keep uric acid levels in a healthy range.', 'uric', 'High uric acid can be uncomfortable and confusing, with long lists of foods to avoid. We simplify it: what to limit, what to enjoy and how to build meals that support healthy levels.', array['Your uric acid has been flagged high in a recent test', 'You get joint discomfort and want to understand food triggers', 'You are unsure which foods are really a problem']::text[], array['Look at your usual diet, hydration and lifestyle', 'Clear guidance on foods to limit versus foods that are fine', 'A balanced plan that does not leave you hungry or restricted']::text[], array['Easy food list: limit, moderate, enjoy', 'Weekly meal plan using everyday foods', 'Hydration and lifestyle tips', 'Follow-up after your next test']::text[], '[{"q":"Do I have to give up all dal and meat?","a":"Not necessarily. Portions and frequency matter more than blanket bans, and your plan will be specific to you."}]'::jsonb, 2),
  ('blood-pressure', 'Hypo / hypertension', 'Practical nutrition for low and high blood pressure.', 'pressure', 'Food, salt, hydration and meal timing all play a part in blood pressure. We focus on small, practical changes that fit your daily routine and work alongside medical care.', array['You have high blood pressure and want to support it through food', 'You experience low blood pressure, dizziness or fatigue', 'You want to cut salt without losing flavour']::text[], array['Review of your readings, routine, medication and eating pattern', 'Gradual, realistic changes rather than a total overhaul', 'Meal structure and hydration tailored to high or low pressure']::text[], array['Tailored meal plan', 'Low-salt cooking and flavour tips', 'Hydration and meal-timing guidance', 'Follow-up to review progress']::text[], '[{"q":"Is this a replacement for my doctor''s advice?","a":"No. Nutrition support complements your medical care. Continue to follow your doctor''s treatment."}]'::jsonb, 3),
  ('sports-nutrition', 'Sports nutrition', 'Fuel, recovery and body-composition planning for active people.', 'sports', 'Training hard needs the right fuel. We plan what and when to eat so you have energy for sessions, recover well and move towards your body-composition goals.', array['You train at the gym, play a sport or run regularly', 'You want to build muscle or cut body fat', 'You are not sure how to eat around your workouts']::text[], array['Understand your training schedule, goals and current diet', 'Plan calories, protein and meal timing around your sessions', 'Review progress and fine-tune every few weeks']::text[], array['Training-day and rest-day plans', 'Pre- and post-workout meal ideas', 'Protein and hydration guidance', 'Regular check-ins as your training changes']::text[], '[{"q":"Do I need supplements?","a":"Often food covers most needs. If supplements make sense for you, your dietitian will explain why and how."}]'::jsonb, 4),
  ('pcos-diet-plans', 'PCOS diet plans', 'Hormone-aware eating that supports cycles, energy and weight.', 'pcos', 'PCOS affects every woman differently. Nutrition can support insulin balance, energy and weight, and make daily life feel more manageable. We build a plan around your symptoms and goals.', array['You have been diagnosed with PCOS or suspect it', 'You have irregular cycles, fatigue or difficulty managing weight', 'You want guidance that is not just ''lose weight''']::text[], array['Listen to your symptoms, cycle pattern, routine and reports', 'Focus on blood-sugar balance, protein, fibre and consistent meals', 'Gentle, sustainable steps that you can keep up']::text[], array['Personalised, PCOS-aware meal plan', 'Guidance on cravings, snacks and meal timing', 'Lifestyle tips for sleep, stress and movement', 'Follow-up to adjust as your body responds']::text[], '[{"q":"Is there a special PCOS diet?","a":"There is no single diet that suits everyone. Your plan is built around your symptoms, preferences and lifestyle."}]'::jsonb, 5)
insert into faqs (question, answer, sort_order) values
  ('How do consultations work?', 'After you book, we meet by WhatsApp call or video, Zoom, Microsoft Teams or in the clinic, whichever suits you. We go through your history, routine and goals, then you receive a personalised plan.', 0),
  ('How do I book a session?', 'Tap Book a Session and choose WhatsApp for the fastest reply, or send an enquiry with your preferred date and time. We will confirm an appointment and send you an appointment card.', 1),
  ('Do I need medical reports?', 'Not for your first conversation. If you have recent reports such as blood sugar, uric acid or thyroid tests, share them, as they help us tailor your plan.', 2),
  ('Will I have to give up my favourite foods?', 'No. Plans use everyday, home-cooked foods and focus on balance, portions and timing rather than strict bans.', 3),
  ('How soon will I see results?', 'It varies from person to person and depends on your goals and consistency. We set a realistic pace together. Results are not guaranteed.', 4),
  ('Is my information kept private?', 'Yes. Your details are used only to arrange and deliver your consultation, and are never shown publicly.', 5);
